package com.portfolio.features.social.entity; import com.portfolio.features.portfolio.entity.Portfolio; import jakarta.persistence.*; import java.util.*; import lombok.*; @Entity @Table(name="social_links") @Getter @Setter @NoArgsConstructor public class SocialLink {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="portfolio_id") private Portfolio portfolio; @Column(nullable=false) private String platform; @Column(nullable=false,columnDefinition="TEXT") private String url; private int sortOrder;}
